<template>
  <div class="mobile-page">
    <header class="mobile-header"><button class="back-button" @click="$router.back()">‹</button><div><b>粮食安全综合监管</b><span>{{ userStore.role?.roleName || roleLevel }} · {{ online ? '在线' : '离线' }}</span></div><button class="refresh-button" @click="load">刷新</button></header>

    <nav class="tab-nav"><button v-for="tab in tabs" :key="tab.key" :class="{ active: activeTab === tab.key }" @click="activeTab = tab.key">{{ tab.label }}</button></nav>

    <template v-if="activeTab === 'overview'">
      <section class="panel"><div class="section-title"><i></i><b>系统态势总览</b><span class="count">{{ events.length }} 条任务</span></div><div class="overview-grid"><button v-for="item in overview" :key="item.key" @click="goTaskFilter(item.key)"><strong>{{ item.count }}</strong><span>{{ item.label }}</span></button></div><p v-if="reminder" class="notice">任务提醒：{{ reminder }}</p></section>
      <section class="panel"><div class="section-title"><i></i><b>风险分布</b></div><div class="risk-bars"><div v-for="item in riskDistribution" :key="item.label"><span>{{ item.label }}</span><b><i :style="{ width: `${item.percent}%` }"></i></b><em>{{ item.count }}</em></div></div></section>
      <section class="panel"><div class="section-title"><i></i><b>任务提醒</b></div><div class="reminder-box"><strong>{{ pendingCount }}</strong><span>条任务等待处理</span><el-button link type="primary" @click="activeTab = 'tasks'">立即处理</el-button></div></section>
      <section class="panel"><div class="section-title"><i></i><b>最近任务</b><span class="count">{{ recentTasks.length }} 条</span></div><div v-for="event in recentTasks" :key="event.id" class="task-card" :class="`task-${event.status}`" @click="selectTask(event); activeTab = 'tasks'"><div class="task-head"><b>{{ event.code }}</b><el-tag size="small" :type="statusType(event.status)">{{ statusName(event.status) }}</el-tag></div><p>{{ event.regionName }} · {{ event.subjectName || '待核实主体' }}</p><div class="task-foot"><span>{{ event.deadline || '截止时间待定' }}</span><span>{{ riskName(event.risk) }} ›</span></div></div><el-empty v-if="!recentTasks.length" description="暂无最近任务" /></section>
      <section class="panel"><div class="section-title"><i></i><b>快速入口</b></div><div class="quick-entry"><button @click="activeTab = 'tasks'">核查任务<span>现场核查与提交</span></button><button @click="activeTab = 'offline'">离线中心<span>缓存与批量上传</span></button><button @click="activeTab = 'audit'">审核抽查<span>审核与随机抽查</span></button></div></section>
    </template>

    <template v-if="activeTab === 'tasks'"><section ref="taskSection" class="panel"><div class="section-title"><i></i><b>核查任务</b><span class="count">{{ filteredTasks.length }} 条</span></div><div class="filter-tabs"><button v-for="filter in taskFilters" :key="filter.key" :class="{ active: taskFilter === filter.key }" @click="taskFilter = filter.key">{{ filter.label }}</button></div><div v-for="event in filteredTasks" :key="event.id" class="task-card rich-task" :class="`task-${event.status}`" @click="selectTask(event)"><div class="task-head"><b>{{ event.code }}</b><el-tag size="small" :type="statusType(event.status)">{{ statusName(event.status) }}</el-tag></div><div class="task-meta"><span>问题：{{ event.desc || '待核实问题' }}</span><span>位置：{{ event.regionName }}</span><span>面积：{{ event.spot?.areaMu || 0 }} 亩</span><span>风险：{{ riskName(event.risk) }}</span><span>截止：{{ event.deadline || '待定' }}</span><span>责任人：{{ event.assignee || event.owner || '待分派' }}</span></div><div class="task-foot"><span>点击进入详情/现场核查</span><span>›</span></div></div><el-empty v-if="!filteredTasks.length" description="暂无符合条件的任务" /></section></template>

    <section v-if="activeTask" class="panel"><div class="section-title"><i></i><b>任务详情与现场核查</b><el-button link type="primary" @click="activeTask = null">收起</el-button></div><div class="spot-info"><p><b>任务编号：</b>{{ activeTask.code }}</p><p><b>图斑位置：</b>{{ activeTask.regionName }}</p><p><b>面积：</b>{{ activeTask.spot?.areaMu || 0 }} 亩　<b>风险：</b>{{ riskName(activeTask.risk) }}</p><p><b>责任人：</b>{{ activeTask.assignee || activeTask.owner || '待分派' }}</p><p><b>中心坐标：</b>{{ centerText(activeTask) }}</p><el-button size="small" @click="navigate(activeTask)">地图导航</el-button></div><div v-if="canCheck(activeTask)" class="check-form"><el-form label-position="top"><el-form-item label="核查结论"><el-radio-group v-model="checkForm.conclusion"><el-radio label="问题属实">问题属实</el-radio><el-radio label="问题不属实">问题不属实</el-radio><el-radio label="部分属实">部分属实</el-radio></el-radio-group></el-form-item><el-form-item label="问题描述"><el-input v-model="checkForm.desc" type="textarea" :rows="3" placeholder="请填写现场核查情况" /></el-form-item><div class="two-col"><el-form-item label="经度"><el-input v-model="checkForm.longitude" /></el-form-item><el-form-item label="纬度"><el-input v-model="checkForm.latitude" /></el-form-item></div><div class="two-col"><el-form-item label="现场照片数量"><el-input-number v-model="checkForm.photos" :min="0" /></el-form-item><el-form-item label="现场视频数量"><el-input-number v-model="checkForm.videos" :min="0" /></el-form-item></div><div class="upload-row"><label>拍照/上传照片<input type="file" accept="image/*" capture="environment" multiple @change="countFiles($event, 'photos')" /></label><label>录像/上传视频<input type="file" accept="video/*" capture="environment" multiple @change="countFiles($event, 'videos')" /></label></div><p class="watermark-tip">现场照片将标记“时间 + 位置”水印（演示记录）</p></el-form><div class="form-actions"><el-button @click="saveOffline">离线保存</el-button><el-button type="primary" @click="submitCheck">提交核查结果</el-button></div></div><div v-else class="detail-box">核查结论：{{ activeTask.checkReport?.conclusion || '待核查' }}<br>问题描述：{{ activeTask.checkReport?.desc || '暂无' }}<br>现场证据：{{ activeTask.checkReport?.photos || 0 }} 张照片、{{ activeTask.checkReport?.videos || 0 }} 个视频</div></section>

    <template v-if="activeTab === 'offline'"><section class="panel"><div class="section-title"><i></i><b>待下载任务</b><span class="count">{{ cachedTasks.length }} 条缓存</span></div><div class="offline-card"><p>将待核查任务下载到本地，无网络也可填写</p><small>最近缓存：{{ cacheTime(cachedTasks) }}</small><el-button size="small" type="primary" @click="downloadTemplates">下载待填报任务</el-button></div></section><section class="panel"><div class="section-title"><i></i><b>离线填报</b><span class="count">{{ cachedReports.length }} 条待上传</span></div><div class="offline-card"><p>已保存的现场核查记录</p><small>上传状态：{{ cachedReports.length ? '待联网批量上传' : '暂无待上传记录' }}</small><div><el-button size="small" @click="openOffline">继续填报</el-button><el-button size="small" type="primary" @click="uploadCache">批量上传</el-button></div></div><div v-for="item in cachedReports" :key="item.id" class="cache-row"><span>{{ item.code }} · {{ cacheDate(item.savedAt) }}</span><small>{{ item.uploaded ? '已上传' : '待上传' }}</small></div></section><section class="panel"><div class="section-title"><i></i><b>历史记录</b><el-button link type="primary" @click="historyVisible = true">查看全部</el-button></div><p class="cache-tip">已完成 {{ history.length }} 条现场填报记录</p><div v-for="item in history.slice(0, 3)" :key="item.id + item.time" class="cache-row"><span>{{ item.code }}</span><small>{{ item.time }}</small></div></section></template>

    <template v-if="activeTab === 'audit'"><section v-if="canAudit" class="panel"><div class="section-title"><i></i><b>市级待审核列表</b><span class="count">{{ reviewingTasks.length }} 条</span></div><div v-for="event in reviewingTasks" :key="event.id" class="audit-row"><div><b>{{ event.code }}</b><span>{{ event.regionName }} · {{ event.subjectName || '待核实主体' }}</span></div><div><el-button size="small" type="success" @click="audit(event, 'pass')">通过</el-button><el-button size="small" type="danger" plain @click="audit(event, 'reject')">打回</el-button></div></div><el-empty v-if="!reviewingTasks.length" description="暂无待审核任务" /></section><section v-else-if="isProvince" class="panel"><div class="section-title"><i></i><b>省级随机抽查</b></div><p class="audit-tip">从权限范围内任务随机抽取现场核查记录，形成抽查闭环。</p><el-button type="warning" @click="randomInspect">随机抽查</el-button><div v-if="randomTask" class="random-form"><p><b>{{ randomTask.code }} · {{ randomTask.regionName }}</b></p><el-form label-position="top"><el-form-item label="抽查结论"><el-select v-model="randomForm.conclusion" style="width:100%"><el-option label="通过" value="通过" /><el-option label="发现问题" value="发现问题" /><el-option label="需补充材料" value="需补充材料" /></el-select></el-form-item><el-form-item label="问题描述"><el-input v-model="randomForm.desc" type="textarea" /></el-form-item><div class="two-col"><el-form-item label="经度"><el-input v-model="randomForm.longitude" /></el-form-item><el-form-item label="纬度"><el-input v-model="randomForm.latitude" /></el-form-item></div><el-form-item label="照片数量"><el-input-number v-model="randomForm.photos" :min="0" /></el-form-item></el-form><el-button type="primary" @click="saveInspection">保存抽查记录</el-button></div><div v-for="item in inspections" :key="item.time" class="history-row"><b>{{ item.code }}</b><span>{{ item.conclusion }}</span><small>{{ item.time }}</small></div></section><section v-else class="panel"><div class="section-title"><i></i><b>核查上报</b></div><p class="audit-tip">当前角色请通过核查任务完成现场填报并上报，提交后由市级统一审核。</p><el-button type="primary" @click="activeTab = 'tasks'">进入核查任务</el-button></section></template>

    <el-dialog v-model="historyVisible" title="历史填报记录" width="92%"><div v-for="item in history" :key="item.id + item.time" class="dialog-history"><b>{{ item.code }} · {{ item.conclusion }}</b><p>{{ item.desc || '暂无描述' }}</p><small>{{ item.time }}</small></div><el-empty v-if="!history.length" description="暂无历史填报记录" /></el-dialog>
  </div>
</template>

<script setup>
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { useUserStore } from '@/stores/user'
import { auditEvent, fetchEvent, fetchEvents, submitCheckReport } from '@/api/fsr'

const userStore = useUserStore(); const events = ref([]); const activeTask = ref(null); const taskSection = ref(null); const online = ref(navigator.onLine); const historyVisible = ref(false); const activeTab = ref('overview'); const taskFilter = ref('all')
const tabs = [{ key: 'overview', label: '态势总览' }, { key: 'tasks', label: '核查任务' }, { key: 'offline', label: '离线中心' }, { key: 'audit', label: '审核抽查' }]
const taskFilters = [{ key: 'all', label: '全部' }, { key: 'checking', label: '待核查' }, { key: 'reviewing', label: '待审核' }, { key: 'recheck', label: '需复查' }, { key: 'closed', label: '已结案' }]
const cachedTasks = ref(read('wzt-food-tasks')); const cachedReports = ref(read('wzt-food-reports')); const history = ref(read('wzt-food-history')); const inspections = ref(read('wzt-food-inspections')); const randomTask = ref(null)
const checkForm = reactive({ conclusion: '问题属实', desc: '', longitude: '', latitude: '', photos: 0, videos: 0 }); const randomForm = reactive({ conclusion: '通过', desc: '', longitude: '', latitude: '', photos: 0 })
const roleLevel = computed(() => { const r = userStore.role || {}; const raw = `${r.role || ''}${r.code || ''}${r.roleName || ''}`.toLowerCase(); if (r.regionCode === '340000' || raw.includes('province') || raw.includes('省')) return '省级'; if (raw.includes('city') || raw.includes('市')) return '市级'; if (raw.includes('town') || raw.includes('township') || raw.includes('乡') || raw.includes('镇')) return '乡镇'; return '县级' })
const isProvince = computed(() => roleLevel.value === '省级'); const canAudit = computed(() => roleLevel.value === '市级'); const canReceive = computed(() => ['县级', '乡镇'].includes(roleLevel.value)); const reviewingTasks = computed(() => events.value.filter(e => e.status === 'reviewing'))
const overview = computed(() => [{ key: 'checking', label: '待核查' }, { key: 'reviewing', label: '待审核' }, { key: 'recheck', label: '需复查' }, { key: 'closed', label: '已结案' }].map(i => ({ ...i, count: events.value.filter(e => e.status === i.key).length })))
const filteredTasks = computed(() => taskFilter.value === 'all' ? events.value : events.value.filter(e => e.status === taskFilter.value))
const recentTasks = computed(() => events.value.slice(0, 3)); const pendingCount = computed(() => events.value.filter(e => ['checking', 'reviewing', 'recheck'].includes(e.status)).length)
const riskDistribution = computed(() => { const total = events.value.length || 1; return [{ label: '高风险', key: 'high', color: '#e85d75' }, { label: '中风险', key: 'medium', color: '#e6a23c' }, { label: '低风险', key: 'low', color: '#2f8c76' }].map(i => ({ ...i, count: events.value.filter(e => e.risk === i.key).length, percent: Math.round(events.value.filter(e => e.risk === i.key).length / total * 100) })) })
const reminder = computed(() => { const n = pendingCount.value; return n ? `您有 ${n} 条任务需要处理` : '' })
const statusNames = { pending: '待接收', checking: '待核查', reviewing: '待审核', rectifying: '整改中', recheck: '需复查', closed: '已结案' }; const statusName = s => statusNames[s] || '未知状态'; const statusType = s => ({ checking: 'warning', reviewing: 'primary', recheck: 'danger', closed: 'success' }[s] || 'info'); const riskName = r => ({ high: '高风险', medium: '中风险', low: '低风险' }[r] || '待评估')
function read(key) { try { return JSON.parse(localStorage.getItem(key) || '[]') } catch { return [] } }; function save(key, value) { localStorage.setItem(key, JSON.stringify(value)) }
const centerText = e => e?.spot?.center?.join?.(', ') || e?.checkReport?.gps || '暂无坐标'; const canCheck = e => ['checking', 'recheck'].includes(e?.status) && canReceive.value
async function load() { const result = await fetchEvents(userStore.role, {}); events.value = Array.isArray(result) ? result : []; if (activeTask.value) activeTask.value = await fetchEvent(activeTask.value.id) }
async function selectTask(e) { activeTask.value = await fetchEvent(e.id); const draft = cachedReports.value.find(i => i.id === e.id); Object.assign(checkForm, draft?.report || { conclusion: '问题属实', desc: '', longitude: '', latitude: '', photos: 0, videos: 0 }) }
function goTaskFilter(status) { activeTab.value = 'tasks'; taskFilter.value = status; taskSection.value?.scrollIntoView({ behavior: 'smooth' }) }
function cacheDate(value) { return value ? new Date(value).toLocaleString('zh-CN') : '暂无时间' }
function cacheTime(list) { return list.length ? cacheDate(Math.max(...list.map(item => item.downloadedAt || 0))) : '暂无缓存' }
function navigate(e) { const c = e?.spot?.center; if (!c?.length) return ElMessage.warning('暂无图斑坐标'); window.open(`https://uri.amap.com/marker?position=${c[0]},${c[1]}&name=${encodeURIComponent(e.regionName || '图斑位置')}`, '_blank') }
function countFiles(ev, type) { checkForm[type] += ev.target.files?.length || 0; ElMessage.success(`${type === 'photos' ? '照片' : '视频'}已加入现场证据，时间地点水印待生成`) }
function saveOffline() { if (!activeTask.value) return; const item = { id: activeTask.value.id, code: activeTask.value.code, report: { ...checkForm }, uploaded: false, savedAt: Date.now() }; cachedReports.value = [...cachedReports.value.filter(i => i.id !== item.id), item]; save('wzt-food-reports', cachedReports.value); ElMessage.success('已保存离线记录') }
async function submitCheck() { if (!activeTask.value) return ElMessage.warning('请先选择任务'); if (!checkForm.desc.trim()) return ElMessage.warning('请填写问题描述'); if (!checkForm.longitude || !checkForm.latitude) return ElMessage.warning('请填写经纬度'); if (!online.value) return saveOffline(); const result = await submitCheckReport(activeTask.value.id, { ...checkForm, gps: `${checkForm.longitude}, ${checkForm.latitude}`, checker: userStore.role?.name }); if (!result?.success) return ElMessage.error(result?.message || '提交失败'); saveHistory(activeTask.value, checkForm); cachedReports.value = cachedReports.value.filter(i => i.id !== activeTask.value.id); save('wzt-food-reports', cachedReports.value); ElMessage.success('核查结果已提交'); activeTask.value = null; load() }
function saveHistory(e, report) { history.value.unshift({ id: e.id, code: e.code, ...report, time: new Date().toLocaleString('zh-CN') }); history.value = history.value.slice(0, 30); save('wzt-food-history', history.value) }
function downloadTemplates() { cachedTasks.value = events.value.filter(e => ['checking', 'recheck'].includes(e.status)).map(e => ({ id: e.id, code: e.code, regionName: e.regionName, spot: e.spot, downloadedAt: Date.now() })); save('wzt-food-tasks', cachedTasks.value); ElMessage.success(`已缓存 ${cachedTasks.value.length} 条待填报任务`) }
function openOffline() { const task = cachedTasks.value.find(t => events.value.some(e => e.id === t.id && ['checking', 'recheck'].includes(e.status))); if (!task) return ElMessage.info('请先下载待填报任务'); selectTask(events.value.find(e => e.id === task.id)) }
async function uploadCache() { if (!online.value) return ElMessage.warning('当前离线'); for (const item of [...cachedReports.value]) { if (item.uploaded) continue; const result = await submitCheckReport(item.id, { ...item.report, gps: `${item.report.longitude}, ${item.report.latitude}`, checker: userStore.role?.name }); if (result?.success) { const e = events.value.find(x => x.id === item.id); if (e) saveHistory(e, item.report); cachedReports.value = cachedReports.value.filter(x => x.id !== item.id) } } save('wzt-food-reports', cachedReports.value); ElMessage.success('缓存数据上传完成'); load() }
async function audit(e, action) { const result = await auditEvent(e.id, action, action === 'pass' ? '材料完整，审核通过' : '材料不充分，请重新核查', userStore.role?.name); if (!result?.success) return ElMessage.error(result?.message || '审核失败'); ElMessage.success(action === 'pass' ? '审核通过' : '已打回重核'); load() }
function randomInspect() { if (!events.value.length) return ElMessage.info('暂无可抽查事件'); randomTask.value = events.value[Math.floor(Math.random() * events.value.length)]; const c = centerText(randomTask.value).split(','); Object.assign(randomForm, { conclusion: '通过', desc: '', longitude: c[0] || '', latitude: c[1]?.trim() || '', photos: 0 }) }
function saveInspection() { if (!randomTask.value) return; inspections.value.unshift({ eventId: randomTask.value.id, code: randomTask.value.code, ...randomForm, inspector: userStore.role?.name, time: new Date().toLocaleString('zh-CN') }); save('wzt-food-inspections', inspections.value.slice(0, 30)); randomTask.value = null; ElMessage.success('抽查记录已保存') }
function syncOnline() { online.value = navigator.onLine }
onMounted(() => { addEventListener('online', syncOnline); addEventListener('offline', syncOnline); load() }); onUnmounted(() => { removeEventListener('online', syncOnline); removeEventListener('offline', syncOnline) })
</script>

